const l=s=>s.split('|');
const s=(title,body,refs,extra={})=>({title:l(title),body:l(body),refs,inspection:true,...extra});
const hot=['regionTube','regionHeatbreak','regionTip'],gears=['pgAssembly','idlerBearing1','idlerBearing2'];
const source={clog:'https://help.prusa3d.com/article/clogged-nozzle-core-one-core-one-l-xl-mk4-s-mk3-9-s_411823',cold:'https://help.prusa3d.com/article/cold-pull-31702-core-one-35702-core-one-l_930551',sensor:'https://help.prusa3d.com/article/nextruder-filament-sensor-core-one-core-one-l-mk4-s-mk3-9-s-xl_465702'};
export function extendMaintenanceTasks(tasks,symptoms){
 const get=id=>tasks.find(t=>t.id===id);
 symptoms.find(x=>x.id==='loading').indices=[0,1,2,3,4];
 const clog=get('clog');
 clog.steps[2].related=['extruder'];
 clog.steps[3].title=l('ギアからホットエンドまで|Between gear and hotend|Mezi kolem a hotendem|Zwischen Antriebsrad und Hotend');
 clog.steps[3].body=l('フィラメントが途中で折れると、送りギアの下からノズルチューブ入口までに破片が残ることがあります。アイドラーを開き、チューブ上端に破片が出ていないか確認します。見える破片の除去と、奥の詰まりは対処を分けます。|A broken piece can remain below the drive gear at the nozzle-tube entrance. Open the idler and inspect the top of the tube for a protruding fragment. A visible fragment and a blockage deeper inside need different treatment.|Ulomený filament může zůstat pod podávacím kolem u vstupu do trubičky trysky. Otevřete idler a zkontrolujte, zda z trubičky vyčnívá úlomek. Viditelný úlomek a ucpání hlouběji vyžadují odlišný postup.|Ein Bruchstück kann unter dem Antriebsrad am Eingang des Düsenrohrs verbleiben. Idler öffnen und prüfen, ob ein Stück oben herausragt. Sichtbares Bruchstück und tiefe Verstopfung erfordern unterschiedliche Verfahren.');
 clog.steps[3].related=['fragment','feed-clear','nozzle'];
 clog.steps[4].body=l('ギアを越えてもノズルから出ない場合は、チューブ内やノズル内部も詰まっている可能性があります。一部でも吐出するならコールドプルを検討します。押し出しで流れが戻らない場合は交換へ進みます。標準のHFノズルに清掃針を通す手順は使いません。|If filament passes the gear but does not emerge, the tube or nozzle may be blocked. Consider a cold pull when some material still extrudes. If pushing fresh filament does not restore flow, proceed to replacement. Do not use the needle procedure with the stock HF nozzle.|Pokud filament projde kolem, ale nevychází ven, může být ucpaná trubička nebo tryska. Při částečné extruzi zvažte cold pull. Nepomůže-li protlačení nového filamentu, přejděte k výměně. U standardní HF trysky nepoužívejte postup s jehlou.|Passiert Filament das Rad, tritt aber nicht aus, können Rohr oder Düse blockiert sein. Bei teilweiser Extrusion Cold Pull erwägen. Stellt frisches Filament den Fluss nicht wieder her, zum Austausch wechseln. Das Nadelverfahren nicht mit der serienmäßigen HF-Düse verwenden.');
 clog.steps[4].related=['feed-clear','coldpull','nozzle'];
 clog.steps[1].related=['sensor-clean'];
 // Each maintenance interval and access method follows the CORE One/+ article.
 get('panels').interval=l('200時間点検時・汚れたとき|At the 200 h check or when dirty|Při kontrole po 200 h nebo znečištění|Bei der 200-h-Prüfung oder Verschmutzung');
 get('rod').steps=[
  s('Y軸ロッドを清掃する|Wipe the Y rods|Otření tyčí Y|Y-Stangen abwischen','左右のロッドを清潔な紙タオルで拭き、ほこりと汚れを落とします。|Wipe both rods with a clean paper towel to remove dust and dirt.|Obě tyče otřete čistou papírovou utěrkou a odstraňte prach i nečistoty.|Beide Stangen mit sauberem Papiertuch von Staub und Schmutz befreien.',[377,566]),
  s('Prusa Lubricantを少量塗る|Apply a little Prusa Lubricant|Nanesení malého množství Prusa Lubricant|Wenig Prusa Lubricant auftragen','Y軸の滑らかなロッドに少量塗ります。X軸リニアレールとは潤滑剤が異なります。|Apply a small amount to the smooth Y rods. The X linear rail uses a different lubricant.|Na hladké tyče Y naneste malé množství. Lineární kolejnice X vyžaduje jiné mazivo.|Wenig auf die glatten Y-Stangen auftragen. Die X-Linearschiene benötigt ein anderes Schmiermittel.',[377,566]),
  s('動きが改善するか確認する|Check for smooth movement|Kontrola plynulého pohybu|Leichtgängigkeit prüfen','清掃と注油の直後でも動きが悪いときだけ、公式ガイドのベアリング取り外し・洗浄・内部グリス塗布を検討します。|Only if movement remains rough after cleaning and lubrication, consider the guide’s bearing removal, alcohol cleaning and internal greasing procedure.|Pouze pokud pohyb zůstává nepravidelný i po čištění a mazání, zvažte demontáž ložisek, čištění alkoholem a vnitřní promazání podle návodu.|Nur bei weiterhin rauem Lauf nach Reinigung und Schmierung den Lagerausbau mit Alkoholreinigung und innerer Schmierung gemäß Anleitung erwägen.',[377,566])];
 get('rail').steps=[
  s('X軸レールの汚れを拭く|Wipe the X rail|Otření kolejnice X|X-Schiene abwischen','清潔で乾いた布かティッシュを使います。キャリッジのゴムを傷めるため、脱脂剤や薬品は使いません。|Use a clean dry cloth or tissue. Avoid degreasers and chemicals that can damage the carriage rubber.|Použijte čistou suchou utěrku. Odmašťovače a chemikálie mohou poškodit pryž vozíku.|Sauberes trockenes Tuch verwenden. Entfetter und Chemikalien können das Gummi am Wagen beschädigen.',[382]),
  s('専用セットで注油する|Use the rail lubrication set|Použití sady pro mazání kolejnic|Schienenschmierset verwenden','注油の目安は3〜6か月です。Microlube GL 261を含む専用セットを使い、注油口は公式写真で確認します。Prusa Lubricantは使いません。|Lubricate every 3–6 months with the dedicated set containing Microlube GL 261. Locate the lubrication points in the official photos. Do not use Prusa Lubricant.|Mažte každých 3–6 měsíců sadou s Microlube GL 261. Mazací místa ověřte na oficiálních fotografiích. Nepoužívejte Prusa Lubricant.|Alle 3–6 Monate das Set mit Microlube GL 261 verwenden. Schmierstellen anhand der offiziellen Fotos bestimmen. Kein Prusa Lubricant verwenden.',[382])];
 get('fans').steps=[
  s('停止・電源切断を確認する|Stop and disconnect power|Zastavení a odpojení napájení|Stillstand und Netztrennung prüfen','電源を切って電源コードを抜きます。回転中のファンに圧縮空気を吹き付けません。|Switch off and unplug. Never direct compressed air at a running fan.|Vypněte tiskárnu a odpojte přívod. Na běžící ventilátor nefoukejte stlačený vzduch.|Ausschalten und Netzstecker ziehen. Laufende Lüfter nicht mit Druckluft anblasen.',[834,791,'fans']),
  s('ほこりと樹脂の糸を除く|Remove dust and plastic threads|Odstranění prachu a vláken plastu|Staub und Kunststofffäden entfernen','ファンのほこりはエア、糸状の樹脂はピンセットで除きます。エア缶は逆さにしません。|Use canned air for dust and tweezers for plastic strands. Keep the can upright.|Prach odstraňte stlačeným vzduchem, vlákna plastu pinzetou. Nádobku neotáčejte dnem vzhůru.|Staub mit Druckluft, Kunststofffäden mit Pinzette entfernen. Dose aufrecht halten.',[834,791,'fans']),
  s('回転エラーが残る場合|If a fan error remains|Pokud chyba ventilátoru přetrvává|Bei anhaltendem Lüfterfehler','回転数監視を無効にして使い続けません。該当するファンの公式交換手順を確認します。|Do not bypass RPM monitoring. Use the replacement guide for the affected fan.|Nevypínejte kontrolu otáček. Použijte návod k výměně příslušného ventilátoru.|Drehzahlüberwachung nicht umgehen. Austauschanleitung für den betroffenen Lüfter verwenden.',[834,791,'fans'],{related:['hotendfan','printfan']})];
 get('extruder').steps=[
  s('アイドラーを開く|Open the idler|Otevření idleru|Idler öffnen','アイドラーナットを持ち上げ、アイドラーシャフトを動かして送りギアを露出させます。ギアボックスは開けません。|Lift the Idler Nut and move the Idler Shaft to expose the drive gear. Keep the gearbox closed.|Zvedněte matici idleru a odklopte hřídel idleru, aby bylo podávací kolo přístupné. Převodovku neotvírejte.|Idler-Mutter anheben und Idler-Welle wegschwenken, um das Antriebsrad freizulegen. Getriebe geschlossen lassen.',gears),
  s('ギアの溝を清掃する|Clean the gear grooves|Čištění drážek kola|Rillen des Antriebsrads reinigen','側面の開口から、エア・真鍮ブラシ・つまようじで削れたフィラメントを取り除きます。ギアとアイドラーベアリングには注油しません。|Remove filament dust through the side opening with air, a brass brush or a toothpick. Do not lubricate the gear or idler bearings.|Bočním otvorem odstraňte zbytky filamentu vzduchem, mosazným kartáčkem nebo párátkem. Kolo ani ložiska idleru nemažte.|Filamentabrieb durch die seitliche Öffnung mit Luft, Messingbürste oder Zahnstocher entfernen. Rad und Idlerlager nicht schmieren.',gears),
  s('破片と通路を確認して閉じる|Inspect the path and close the idler|Kontrola cesty a zavření idleru|Kanal prüfen und Idler schließen','ギアの下とノズルチューブ上端も確認します。詰まりが残る場合は、確認箇所をホットエンドまで追います。清掃が終わったらアイドラーとスイベルを閉じます。張力ネジを調整した場合、通常の材料ではネジ先端をIdler Nutの前面と同じ位置に合わせます。TPU/TPEなどのフレキシブル材ではこの基準より緩くし、ギアがフィラメントを軽く押す程度に調整します。公式のフレキシブル材ガイドに従ってください。|Inspect below the gear and at the top of the nozzle tube. Trace any remaining blockage toward the hotend. After cleaning, close the idler and swivel. If the tension screws were adjusted, align their tips with the front face of the Idler Nut as the normal-material reference. For TPU/TPE and other flexible filaments, use a looser setting so the gears grip the filament only gently. Follow the official flexible-material guide.|Zkontrolujte prostor pod kolem a horní konec trubičky. Zbývající ucpání sledujte k hotendu. Po čištění zavřete idler a otočný díl. Pokud jste upravili napínací šrouby, u běžných materiálů zarovnejte jejich konce s přední plochou matice idleru. Pro TPU/TPE a jiné pružné filamenty nastavte menší přítlak, aby podávací kola filament jen lehce svírala. Postupujte podle oficiálního návodu pro pružné materiály.|Unter dem Rad und oben am Düsenrohr prüfen. Verbleibende Blockierung zum Hotend verfolgen. Nach der Reinigung Idler und Schwenkhebel schließen. Bei verstellten Spannschrauben deren Spitzen für übliche Materialien bündig zur Vorderfläche der Idler-Mutter ausrichten. Für TPU/TPE und andere flexible Filamente den Anpressdruck geringer einstellen, sodass die Zahnräder das Filament nur sanft greifen. Die offizielle Anleitung für flexible Materialien beachten.',hot,{source:source.clog,related:['clog','fragment'],supplementalSources:[{"label":["CORE Oneのアイドラー張力","CORE One idler tension","Přítlak idleru CORE One","Idler-Anpressdruck am CORE One"],"url":"https://help.prusa3d.com/article/idler-screw-tension_177367#core-one-mk4-s-mk39-xl"},{"label":["フレキシブル材の送り圧","Feed pressure for flexible materials","Přítlak pro pružné materiály","Anpressdruck für flexible Materialien"],"url":"https://help.prusa3d.com/article/flexible-materials_2057#important-rules-for-successful-printing-with-flexible-filaments"}]})];
 get('extruder').steps.forEach(x=>{x.transparent=[790,794,816];x.camera='hotend-perspective';});
 get('electronics').steps=[
  s('電源を切り、コードを抜く|Switch off and unplug|Vypnutí a odpojení|Ausschalten und Netzstecker ziehen','電気接続に触れる前に、背面スイッチを切って電源コードを抜きます。|Switch off at the rear and unplug before touching electrical connections.|Před dotykem elektrických spojů vypněte zadní vypínač a odpojte napájení.|Vor dem Berühren elektrischer Anschlüsse hinten ausschalten und Netzstecker ziehen.',['psu']),
  s('xBuddyの接続を点検する|Inspect xBuddy connections|Kontrola připojení xBuddy|xBuddy-Anschlüsse prüfen','ネジ止め端子の緩みと、コネクターの差し込みを確認します。ラッチを押さずに端子を引き抜きません。|Check screw terminals and seated plugs. Release each locking latch before unplugging.|Zkontrolujte šroubové svorky a zasunutí konektorů. Před odpojením uvolněte západku.|Schraubklemmen und Steckersitz prüfen. Vor dem Abziehen die Verriegelung lösen.',['xBuddy','xBuddyExtension'],{camera:'back',transparent:[206]}),
  s('LoveBoardの接続を点検する|Inspect LoveBoard connections|Kontrola připojení LoveBoard|LoveBoard-Anschlüsse prüfen','LoveBoardのプラグが正しく固定され、配線が傷んでいないか確認します。|Check that LoveBoard plugs are seated and that wiring is undamaged.|Ověřte správné zasunutí konektorů LoveBoard a nepoškozené vodiče.|Sitz der LoveBoard-Stecker und unbeschädigte Leitungen prüfen.',['loveBoard'],{camera:'wiring-perspective',transparent:[858,790,794,816]}),
  s('ベッド・電源・xLCDを点検する|Inspect bed, PSU and xLCD|Kontrola podložky, zdroje a xLCD|Heizbett, Netzteil und xLCD prüfen','ベッド・電源ユニット・xLCDの接続も点検します。完了後にカバーと配線の挟み込みを確認してから電源を戻します。|Inspect heatbed, PSU and xLCD connections too. Check covers and trapped wires before reconnecting power.|Zkontrolujte také připojení podložky, zdroje a xLCD. Před zapnutím ověřte kryty a nepřiskřípnuté vodiče.|Auch Heizbett-, Netzteil- und xLCD-Anschlüsse prüfen. Vor dem Einschalten Abdeckungen und eingeklemmte Leitungen prüfen.',['heatbed','psu','lcd'])];
 const add=(id,title,url,steps)=>tasks.push({id,title:l(title),category:1,interval:l('症状に合わせて選択|Choose for the symptom|Zvolte podle příznaku|Nach Symptom wählen'),source:url,steps});
 add('feed-clear','新しいフィラメントで詰まりを除く|Clear with fresh filament|Uvolnění novým filamentem|Mit frischem Filament lösen',source.clog,[
  s('対処方法を選ぶ|Choose the method|Volba postupu|Verfahren wählen','HF・標準流量ノズルの両方が対象です。まずアンロードを試します。外部のヒーターや炎でノズルを熱しません。|For HF and standard-flow nozzles. First try unloading. Heat only through the printer menu, never with an external heater or flame.|Pro HF i standardní trysky. Nejprve zkuste vysunout filament. Nahřívejte pouze menu tiskárny, nikoli vnějším ohřevem či plamenem.|Für HF- und Standarddüsen. Zuerst Entladen versuchen. Nur über das Druckermenü heizen, niemals mit externer Wärmequelle oder Flamme.',hot,{firmwareActions:["unload"]}),
  s('入口とアイドラーを開ける|Access the inlet and idler|Zpřístupnění vstupu a idleru|Eingang und Idler zugänglich machen','アイドラーを開き、Nextruder上部のフィッティングがある場合は取り外します。PLAを約40 cm用意します。|Open the idler and remove any fitting at the top of the Nextruder. Prepare about 40 cm of PLA.|Otevřete idler a případně odstraňte horní šroubení Nextruderu. Připravte asi 40 cm PLA.|Idler öffnen und vorhandenes oberes Fitting am Nextruder entfernen. Etwa 40 cm PLA vorbereiten.',[817,...gears]),
  s('使っていた材料に合わせて加熱する|Heat for the previous material|Ohřev podle předchozího materiálu|Für das vorherige Material aufheizen','Control → Temperature → Nozzleを開きます。PLAを使っていた場合は260 °C、PETG・ASAなどなら280 °Cに設定します。高温部に触れません。|Open Control → Temperature → Nozzle. Use 260 °C after PLA or 280 °C after higher-temperature materials such as PETG or ASA. Avoid hot parts.|Otevřete Control → Temperature → Nozzle. Po PLA nastavte 260 °C, po PETG, ASA a dalších vysokoteplotních materiálech 280 °C. Nedotýkejte se horkých částí.|Control → Temperature → Nozzle öffnen. Nach PLA 260 °C, nach höher temperierten Materialien wie PETG oder ASA 280 °C einstellen. Heiße Teile nicht berühren.',hot,{firmwareActions:["heat"]}),
  s('到達後2分待つ|Wait two minutes at temperature|Dvě minuty na cílové teplotě|Zwei Minuten bei Zieltemperatur warten','設定温度に達してから2分待ち、先端から樹脂が流れ始めるか確認します。|Wait two minutes after reaching the set temperature; check for material flowing from the tip.|Po dosažení nastavené teploty počkejte dvě minuty a sledujte, zda ze špičky vytéká materiál.|Nach Erreichen der Solltemperatur zwei Minuten warten und auf Materialfluss aus der Spitze achten.',['regionTip']),
  s('新しいPLAを上から送る|Feed fresh PLA from above|Zavedení nového PLA shora|Frisches PLA von oben zuführen','用意したPLAを上からNextruderへ押し込みます。流れが戻ったらアイドラーとスイベルを閉じ、押し込んだPLAをアンロードします。外した継手とBowden bendを元に戻してから、通常のロードや印刷を行います。テストには実際の材料・ノズルの径とHF／標準流量に合う温度とスライサープロファイルを使います。|Push the prepared PLA into the Nextruder from above. If flow returns, close the idler and swivel and unload the PLA used for clearing. Refit the removed fitting and Bowden bend before normal loading or printing. Use the temperature and slicer profile for the actual material, nozzle diameter and HF or standard flow.|Připravené PLA zatlačte do Nextruderu shora. Obnoví-li se tok, zavřete idler a otočný díl a vysuňte PLA použité k čištění. Před běžným zaváděním či tiskem vraťte šroubení i Bowden bend. Použijte teplotu a profil pro skutečný materiál, průměr trysky a HF či standardní průtok.|PLA von oben in den Nextruder schieben. Kehrt der Fluss zurück, Idler und Schwenkhebel schließen und das zum Reinigen verwendete PLA entladen. Vor normalem Laden oder Drucken entferntes Fitting und Bowden bend wieder montieren. Temperatur und Slicerprofil auf Material, Düsendurchmesser und HF- oder Standarddurchfluss abstimmen.',[817,...hot],{supplementalSources:[{label:l('アイドラー・継手の復旧|Idler and fitting reassembly|Sestavení idleru a šroubení|Idler und Fitting wieder montieren'),url:source.cold+'#manual-cold-pull'}]}),
  s('流れが戻らない場合|If flow does not return|Pokud se tok neobnoví|Wenn kein Fluss zurückkehrt','流れが戻らなければコールドプルも難しいため、ノズル交換を確認します。チューブ上端につかめる破片が見える場合は破片除去を選びます。分解へ進む前にCOOLDOWNで完全に冷まし、電源を切ってコードを抜きます。|If flow has not returned, a cold pull is unlikely to work; review nozzle replacement. If a grippable fragment protrudes from the tube, use fragment removal. Before disassembly, select COOLDOWN, wait until fully cool, switch off and unplug.|Neobnoví-li se tok, cold pull pravděpodobně nepomůže; projděte výměnu trysky. Vyčnívá-li uchopitelný úlomek, použijte jeho vytažení. Před demontáží zvolte COOLDOWN, nechte zcela vychladnout, vypněte a odpojte napájení.|Ohne wiederhergestellten Fluss ist Cold Pull kaum möglich; Düsenwechsel prüfen. Ragt ein greifbares Stück aus dem Rohr, dessen Entfernung wählen. Vor dem Zerlegen COOLDOWN wählen, vollständig abkühlen lassen, ausschalten und Netzstecker ziehen.',hot,{related:['fragment','nozzle','clog']})]);
 add('fragment','折れたフィラメントを取り除く|Remove a broken filament fragment|Vyjmutí ulomeného filamentu|Abgebrochenes Filament entfernen',source.clog,[
  s('破片がつかめるか確認する|Check for a grippable end|Kontrola uchopitelného konce|Greifbares Ende prüfen','スイベルを持ち上げてロックを外し、アイドラーを開きます。送りギアの下のノズルチューブ上端に、ペンチでつかめる破片が見える場合だけ次へ進みます。見えない破片へペンチを差し込みません。|Lift the swivel to unlock and open the idler. Continue only if a grippable fragment protrudes from the nozzle tube below the drive gear. Do not insert pliers toward an unseen fragment.|Zvedněte otočný díl, odjistěte a otevřete idler. Pokračujte pouze tehdy, pokud z horního konce trubičky pod podávacím kolem vyčnívá úlomek, který lze uchopit kleštěmi. Kleště nezasouvejte k neviditelnému úlomku.|Schwenkhebel anheben, entriegeln und Idler öffnen. Nur fortfahren, wenn oben aus dem Düsenrohr unter dem Antriebsrad ein mit der Zange greifbares Stück herausragt. Nicht mit der Zange nach unsichtbaren Bruchstücken suchen.',['regionTube',...gears]),
  s('ノズルを280 °Cにする|Heat the nozzle to 280 °C|Nahřátí trysky na 280 °C|Düse auf 280 °C heizen','プリンターの温度メニューで280 °Cにし、到達を表示で確認してから破片を引き抜きます。高温部に触れず、配線をつかまないでください。|Set 280 °C using the printer menu and wait for the display to reach it before pulling. Avoid hot parts and do not grip wires.|V menu nastavte 280 °C a před vytažením vyčkejte na dosažení teploty na displeji. Nedotýkejte se horkých částí a nesvírejte vodiče.|Im Druckermenü 280 °C einstellen und vor dem Ziehen das Erreichen der Temperatur am Display abwarten. Heiße Teile nicht berühren und keine Leitungen greifen.',hot,{firmwareActions:['heat']}),
  s('破片を少しずつ真上へ引く|Pull the fragment upward gradually|Postupné vytažení úlomku vzhůru|Bruchstück schrittweise nach oben ziehen','見えているフィラメントをラジオペンチでつかみ、上へ少しずつ引き出します。チューブから完全に抜けるまで続けます。|Grip the visible filament with needle-nose pliers and draw it upward bit by bit until it clears the tube.|Viditelný filament uchopte špičatými kleštěmi a postupně táhněte vzhůru, dokud neopustí trubičku.|Sichtbares Filament mit Spitzzange greifen und Stück für Stück nach oben ziehen, bis es ganz aus dem Rohr ist.',['regionTube','regionHeatbreak']),
  s('除去後に通りを確認する|Check the path after removal|Kontrola po odstranění|Kanal nach Entfernung prüfen','取り除けたら、アイドラーを閉じてコールドプルへ進みます。ノズルが完全に詰まっている場合は、先に新しいフィラメントで流れを戻します。除去できず交換へ進むときはCOOLDOWNで完全に冷まし、電源を切ってコードを抜きます。|After removal, close the idler and proceed to a cold pull. If the nozzle is still fully blocked, first restore flow with fresh filament. If removal fails and replacement is needed, select COOLDOWN, cool fully, switch off and unplug.|Po odstranění zavřete idler a pokračujte cold pullem. Při úplném ucpání nejprve obnovte tok novým filamentem. Pokud vytažení selže a je nutná výměna, zvolte COOLDOWN, nechte vychladnout, vypněte a odpojte napájení.|Nach der Entfernung Idler schließen und mit Cold Pull fortfahren. Bei weiterhin vollständiger Blockierung zuerst mit frischem Filament den Fluss herstellen. Falls die Entfernung scheitert und ein Austausch nötig ist, COOLDOWN wählen, vollständig abkühlen lassen, ausschalten und Netzstecker ziehen.',hot,{related:['coldpull','feed-clear','nozzle']})]);
 add('coldpull','コールドプル（自動）|Automatic cold pull|Automatický cold pull|Automatischer Cold Pull',source.cold,[
  s('部分詰まりか確認する|Check for partial flow|Kontrola částečného průtoku|Teilweisen Fluss prüfen','一部でも樹脂が出るノズルが対象です。完全に詰まっている場合は詰まり対処へ戻ります。Nozzle Xにはこの方法を使いません。|Use when some filament still extrudes. Return to blockage treatment if fully jammed. Do not use this method with Nozzle X.|Použijte, pokud stále dochází k částečné extruzi. Při úplném ucpání se vraťte k řešení ucpání. Nepoužívejte pro Nozzle X.|Bei noch teilweise extrudierendem Filament verwenden. Bei vollständiger Blockierung zur Verstopfungsbehandlung zurückkehren. Nicht für Nozzle X verwenden.',['regionTip'],{related:['feed-clear','fragment']}),
  s('PLAを用意し、自動手順を開始する|Prepare PLA and start the routine|Příprava PLA a spuštění postupu|PLA vorbereiten und Ablauf starten','PLAを少なくとも30 cm用意します。LCDのControl → Cold Pullを選び、画面の指示に従います。|Prepare at least 30 cm of PLA. Select Control → Cold Pull and follow the display.|Připravte alespoň 30 cm PLA. Zvolte Control → Cold Pull a postupujte podle displeje.|Mindestens 30 cm PLA vorbereiten. Control → Cold Pull wählen und den Displayanweisungen folgen.',['lcd']),
  s('冷却・加熱・アンロードを待つ|Wait for cooling, heating and unloading|Chlazení, ohřev a vysunutí|Kühlen, Heizen und Entladen abwarten','必要な冷却と再加熱をプリンターが自動で行います。温度はファームウェアのバージョンにより異なるため、実機の表示に従い、手動で変更しないでください。|The printer handles cooling and reheating automatically. Temperatures vary by firmware version; follow the printer display without changing them manually.|Tiskárna sama provede potřebné chlazení a opětovný ohřev. Teploty se liší podle verze firmwaru; řiďte se displejem tiskárny a neměňte je ručně.|Der Drucker kühlt und heizt automatisch. Die Temperaturen hängen von der Firmware-Version ab; der Druckeranzeige folgen und sie nicht manuell ändern.',hot),
  s('フィラメントを上へ抜く|Withdraw the filament upward|Vytažení filamentu vzhůru|Filament nach oben herausziehen','画面の指示に従い、最後は手で上に引き抜きます。引っ掛かる場合はアイドラーを開きます。|Follow the prompts and finish by pulling the filament upward by hand. Open the idler if it catches.|Podle pokynů filament nakonec rukou vytáhněte vzhůru. Pokud se zachytí, otevřete idler.|Anweisungen befolgen und Filament zum Schluss von Hand nach oben ziehen. Bei Widerstand Idler öffnen.',[817,...hot]),
  s('引き抜いた先端を確認する|Inspect the pulled tip|Kontrola vytažené špičky|Herausgezogene Spitze prüfen','古い樹脂や焦げた汚れを確認し、きれいになるまで必要に応じて繰り返します。終了後は、開いたアイドラーとスイベルを閉じ、アクセスのために外した継手やBowden bendがあれば戻します。流れが戻らなければ詰まり対処に戻ります。|Check for old material or burnt debris; repeat as needed until clean. When finished, close any opened idler and swivel and refit any fitting or Bowden bend removed for access. If flow is not restored, return to blockage treatment.|Zkontrolujte starý materiál či spálené nečistoty a podle potřeby opakujte do vyčištění. Nakonec zavřete otevřený idler a otočný díl a vraťte případně sejmuté šroubení či Bowden bend. Neobnoví-li se tok, vraťte se k řešení ucpání.|Auf altes Material und verbrannte Rückstände prüfen; bei Bedarf bis zur sauberen Spitze wiederholen. Abschließend geöffnete Idler und Schwenkhebel schließen und für den Zugang entfernte Fittings oder Bowden bend wieder montieren. Ohne wiederhergestellten Fluss zur Verstopfungsbehandlung zurückkehren.',hot,{related:['clog','nozzle']})]);
 add('sensor-clean','Nextruderセンサーの清掃|Clean the Nextruder sensor|Čištění senzoru Nextruderu|Nextruder-Sensor reinigen',source.sensor,[
  s('入口の清掃穴を確認する|Locate the cleaning opening|Nalezení čisticího otvoru|Reinigungsöffnung finden','Nextruder上部の小さな清掃穴を公式写真と照合します。エアを入れる清掃穴と、フィラメントを出し入れする入口は別です。糸を引いていない、切り口のきれいなフィラメントを用意します。|Match the small top cleaning hole to the official photo. The air-cleaning hole and the filament inlet are separate openings. Prepare filament with a clean, non-stringy end.|Malý čisticí otvor nahoře porovnejte s oficiální fotografií. Otvor pro vzduch a vstup pro filament jsou oddělené. Připravte filament s čistým koncem bez vláken.|Kleine Reinigungsöffnung oben mit dem offiziellen Foto vergleichen. Luft-Reinigungsöffnung und Filamenteingang sind getrennte Öffnungen. Filament mit sauberem, fadenfreiem Ende vorbereiten.',[817]),
  s('エアとフィラメントで清掃する|Clean with air and filament|Čištění vzduchem a filamentem|Mit Luft und Filament reinigen','小さな清掃穴からエアを吹き、もう片方の手でフィラメントを入口へ何度か出し入れします。エア缶は逆さにしません。|Blow air into the small cleaning hole. With the other hand, repeatedly insert and withdraw filament through the filament inlet. Keep the can upright.|Do malého čisticího otvoru foukejte vzduch. Druhou rukou opakovaně zasouvejte a vysouvejte filament jeho vstupem. Nádobku držte vzpřímeně.|Luft in die kleine Reinigungsöffnung blasen. Mit der anderen Hand Filament mehrfach durch den Filamenteingang ein- und ausführen. Dose aufrecht halten.',[817]),
  s('エアがない場合|Without compressed air|Bez stlačeného vzduchu|Ohne Druckluft','先端に糸のないフィラメントを何度か出し入れします。この方法だけでは汚れが落ちない場合もあります。|Repeatedly insert and withdraw clean-ended filament. This alone may not remove all debris.|Opakovaně zasuňte a vysuňte filament s čistým koncem. Samotný tento postup nemusí nečistoty odstranit.|Filament mit sauberem Ende wiederholt ein- und ausführen. Dies allein entfernt nicht immer alle Rückstände.',[817]),
  s('改善しない場合は分解条件を確認する|Check conditions before disassembly|Podmínky před demontáží|Voraussetzungen vor Demontage prüfen','センサー取り外しはPG-assembly-adapterが必要です。アンロード・完全冷却・電源切断の後、関連する作業の「Nextruder内部の清掃（上級）」で分解・清掃・復旧を進め、最後にギアボックス調整を実行します。|Sensor removal needs the PG-assembly-adapter. Unload, cool fully and switch off, open Nextruder internal cleaning (advanced) in the related procedures for disassembly, cleaning and reassembly, then align the gearbox.|Demontáž senzoru vyžaduje PG-assembly-adapter. Vysuňte filament, nechte zcela vychladnout, vypněte a v souvisejících postupech otevřete Vnitřní čištění Nextruderu (pokročilé) pro demontáž, čištění a sestavení. Nakonec proveďte zarovnání převodovky.|Sensorausbau benötigt den PG-assembly-adapter. Entladen, vollständig abkühlen, ausschalten und unter den zugehörigen Aufgaben Nextruder-Innenreinigung (fortgeschritten) für Ausbau, Reinigung und Zusammenbau öffnen. Abschließend das Getriebe ausrichten.',[817,'pgAssembly'],{related:['sensor-service','clog']})]);
 for(const id of ['feed-clear','fragment','coldpull','sensor-clean'])for(const x of get(id).steps){x.camera=x.refs.includes('lcd')?'front':'hotend-perspective';x.transparent=[790,794,816,858];x.headOnly=!x.refs.includes('lcd');}
 // Phase identities belong to the authored steps, independently of language.
 const coldPhases=[[],['introduction','prepare_filament'],['cool_down','heat_up','automatic_pull'],['manual_pull'],['pull_done']];
 for(const [i,step]of get('coldpull').steps.entries())if(i){step.firmwareActions=['coldpull'];step.firmwarePhases=coldPhases[i];step.firmwareMenu=i===1;}
 // Relevant omissions from the brief working notes; operation IDs stay stable.
 for(const id of ['hotend','nozzle','hotendfan','printfan']){
  const a=get(id),replace=(action,body)=>{const x=a.steps.find(x=>x.action===action);if(x)x.body=l(body);};
  replace('unplug','ラッチを押してヒーター、サーミスターの順に抜きます。端子や細い配線を引っ張らないでください。|Release the latches; unplug the heater, then the thermistor. Do not pull on terminals or thin wires.|Uvolněte západky; odpojte topení a potom termistor. Netahejte za kontakty ani tenké vodiče.|Verriegelungen lösen; Heizung, dann Thermistor abziehen. Nicht an Kontakten oder dünnen Leitungen ziehen.');
  replace('cover-in','配線がはみ出さないよう内側へ収め、カバーの下側を先に掛けます。Nextruder側へ押し込み、配線を挟んでいないことを確認して元のネジで固定します（通常はM3×10、初期型は取り外した2本のM3×10bT）。ベッドの保護材も外します。|Tuck the wires inside without protruding. Hook the cover bottom first, press toward the Nextruder and check for trapped wires. Refit the original fasteners: normally M3×10, or the two removed M3×10bT on early covers. Remove the bed protection.|Vodiče uložte dovnitř bez vyčnívání. Zahákněte spodek krytu, přitlačte k Nextruderu a ověřte, že kabely nejsou skřípnuté. Vraťte původní šrouby: obvykle M3×10, u raných krytů dva sejmuté M3×10bT. Odstraňte ochranu podložky.|Leitungen ohne Überstand innen verstauen. Abdeckung unten einhaken, zum Nextruder drücken und auf eingeklemmte Kabel prüfen. Originalschrauben einsetzen: normalerweise M3×10, bei frühen Abdeckungen die zwei entfernten M3×10bT. Heizbettschutz entfernen.');
 }
 const nozzle=get('nozzle');
 nozzle.steps[0].body=l('標準NextruderのPrusa Nozzleだけを交換し、ヒーターブロック・ヒーター・サーミスターは再使用します。この通常手順ではホットエンド一式を取り外し、室温でノズルを交換します。HFにも対応します。本体に残して交換する場合は、下の公式交換治具の専用手順を使います。HT Hotend・V6アダプターは対象外です。|Replace only the standard Nextruder Prusa Nozzle, reusing the heater block, heater and thermistor. This standard method removes the hotend and changes the nozzle at room temperature; HF is supported. For an in-printer swap, follow the official tool instructions linked below. HT Hotend and V6 adapters need separate guides.|Vyměňte pouze Prusa Nozzle standardního Nextruderu; topný blok, topení a termistor zůstávají. Běžný postup vyjme hotend a mění trysku při pokojové teplotě, i pro HF. Pro výměnu v tiskárně použijte odkazovaný oficiální přípravek a jeho návod. HT Hotend a V6 vyžadují jiné návody.|Nur die Prusa Nozzle des Standard-Nextruders austauschen; Heizblock, Heizung und Thermistor werden weiterverwendet. Hierzu das Hotend ausbauen und die Düse bei Raumtemperatur wechseln, auch HF. Für einen Wechsel im Drucker die verlinkte offizielle Werkzeuganleitung verwenden. HT Hotend und V6 benötigen eigene Anleitungen.');
 // Promote the two entry points most often needed while troubleshooting.
 for(const id of ['rod','rail','fans','extruder','electronics'])get(id).revision=2;
 get('fans').revision=3;
 get('extruder').revision=4;
 for(const id of ['hotend-clean','hotendfan','printfan','feed-clear','fragment','coldpull','sensor-clean'])get(id).revision=2;
 get('sensor-clean').revision=3;
 const order=['clog','nozzle','coldpull','feed-clear','fragment','hotend','hotend-clean'];
 tasks.sort((a,b)=>(order.includes(a.id)?order.indexOf(a.id):order.length)-(order.includes(b.id)?order.indexOf(b.id):order.length));
}
